-- TMDB-MOVIE-PREPROCESS-071, step 1 (fourth pass): what P361 and P527 would add to the award
-- families once wikidata-crawler loads them on cached entities.
-- Read-only: every write goes to temporary tables.
--
-- The preview (check-071-award-wins-preview.sql, pass H) shows that the family by P31 misses
-- most categories, because Wikidata attaches them by P361 (part of) on the category or by P527
-- (has parts) on the family, two properties the crawler does not load on cached entities.
-- The pairs below are a snapshot of the live Wikidata query service on 2026-11-10:
--   SELECT DISTINCT ?c ?g ?route WHERE { ?g wdt:P31 wd:Q107655869 .
--     { ?c wdt:P361 ?g BIND('P361' AS ?route) } UNION { ?g wdt:P527 ?c BIND('P527' AS ?route) } }
-- (12338 pairs). They are a yardstick for this measure only, never a build source.
--
-- What this file answers:
--   L1. how many of our award categories reach a family by these pairs
--   L2. is the family itself in our base, and known there as a group of awards (its own P31)?
--       If not, loading P361 on the category is not enough: the family has to be cached too.
--   L3. projected coverage once loaded, by the same name yardstick as pass H
--   L4. the families missing from our base, by the categories and winners they would carry
--   L5. categories that would reach several families

SELECT NOW() AS NOW_;

DROP TEMPORARY TABLE IF EXISTS tmp_071_live;
CREATE TEMPORARY TABLE tmp_071_live (
  ID_CATEGORY varchar(50) NOT NULL,
  ID_GROUP varchar(50) NOT NULL,
  ROUTE varchar(5) NOT NULL,
  KEY ID_CATEGORY (ID_CATEGORY),
  KEY ID_GROUP (ID_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------------------------
-- Our side: the award categories of T2S (AWARD_SOURCE 'P166'), their winners (distinct
-- entities, read from the counts of T_WC_T2S_AWARD), and the groups of awards our base knows.
-- ---------------------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_071_cat;
CREATE TEMPORARY TABLE tmp_071_cat (PRIMARY KEY (ID_CATEGORY))
ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
AS
SELECT a.ID_WIKIDATA AS ID_CATEGORY, MAX(a.AWARD_NAME) AS AWARD_NAME,
       MAX(COALESCE(a.MOVIE_COUNT, 0) + COALESCE(a.SERIE_COUNT, 0) + COALESCE(a.PERSON_COUNT, 0)) AS WINNERS
FROM T_WC_T2S_AWARD a
WHERE a.AWARD_SOURCE = 'P166' AND a.ID_WIKIDATA <> ''
GROUP BY a.ID_WIKIDATA;

DROP TEMPORARY TABLE IF EXISTS tmp_071_dbgroup;
CREATE TEMPORARY TABLE tmp_071_dbgroup (PRIMARY KEY (ID_GROUP))
ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
AS
SELECT DISTINCT gs.ID_WIKIDATA AS ID_GROUP
FROM T_WC_WIKIDATA_ITEM_VALUE gv
JOIN T_WC_WIKIDATA_STATEMENT gs ON gs.ID_STATEMENT = gv.ID_STATEMENT
WHERE gv.ID_ITEM = 'Q107655869' AND gs.ID_PROPERTY = 'P31'
  AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated');

-- The live pairs that land on one of our categories, with what our base knows of the family.
DROP TEMPORARY TABLE IF EXISTS tmp_071_livecat;
CREATE TEMPORARY TABLE tmp_071_livecat (KEY ID_CATEGORY (ID_CATEGORY), KEY ID_GROUP (ID_GROUP))
ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
AS
SELECT l.ID_CATEGORY, l.ID_GROUP,
       MAX(l.ROUTE = 'P361') AS BY_P361,
       MAX(l.ROUTE = 'P527') AS BY_P527,
       MAX(i.ID_WIKIDATA IS NOT NULL) AS GROUP_IN_ITEM,
       MAX(g.ID_GROUP IS NOT NULL) AS GROUP_KNOWN,
       MAX(c.WINNERS) AS WINNERS
FROM tmp_071_live l
JOIN tmp_071_cat c ON c.ID_CATEGORY = l.ID_CATEGORY
LEFT JOIN T_WC_WIKIDATA_ITEM i ON i.ID_WIKIDATA = l.ID_GROUP
LEFT JOIN tmp_071_dbgroup g ON g.ID_GROUP = l.ID_GROUP
WHERE l.ID_CATEGORY <> l.ID_GROUP
GROUP BY l.ID_CATEGORY, l.ID_GROUP;

-- The families a category reaches today, by its own P31 toward a group our base knows.
DROP TEMPORARY TABLE IF EXISTS tmp_071_p31cat;
CREATE TEMPORARY TABLE tmp_071_p31cat (KEY ID_CATEGORY (ID_CATEGORY))
ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
AS
SELECT DISTINCT c.ID_CATEGORY, pv.ID_ITEM AS ID_GROUP
FROM tmp_071_cat c
JOIN T_WC_WIKIDATA_STATEMENT ps ON ps.ID_WIKIDATA = c.ID_CATEGORY AND ps.ID_PROPERTY = 'P31'
JOIN T_WC_WIKIDATA_ITEM_VALUE pv ON pv.ID_STATEMENT = ps.ID_STATEMENT
JOIN tmp_071_dbgroup g ON g.ID_GROUP = pv.ID_ITEM
WHERE (ps.`RANK` IS NULL OR ps.`RANK` <> 'deprecated') AND pv.ID_ITEM <> c.ID_CATEGORY;

-- One line per category: what it has today, what the live pairs would give it.
DROP TEMPORARY TABLE IF EXISTS tmp_071_proj;
CREATE TEMPORARY TABLE tmp_071_proj (PRIMARY KEY (ID_CATEGORY))
ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
AS
SELECT c.ID_CATEGORY, c.AWARD_NAME, c.WINNERS,
       COALESCE(t.N_P31, 0) AS N_P31,
       COALESCE(x.N_LIVE, 0) AS N_LIVE,
       COALESCE(x.N_LIVE_KNOWN, 0) AS N_LIVE_KNOWN,
       COALESCE(x.N_P361_KNOWN, 0) AS N_P361_KNOWN,
       COALESCE(x.N_P527_KNOWN, 0) AS N_P527_KNOWN
FROM tmp_071_cat c
LEFT JOIN (SELECT ID_CATEGORY, COUNT(*) AS N_P31 FROM tmp_071_p31cat GROUP BY ID_CATEGORY) t ON t.ID_CATEGORY = c.ID_CATEGORY
LEFT JOIN (SELECT ID_CATEGORY, COUNT(*) AS N_LIVE, SUM(GROUP_KNOWN) AS N_LIVE_KNOWN,
                  SUM(GROUP_KNOWN = 1 AND BY_P361 = 1) AS N_P361_KNOWN,
                  SUM(GROUP_KNOWN = 1 AND BY_P527 = 1) AS N_P527_KNOWN
           FROM tmp_071_livecat GROUP BY ID_CATEGORY) x ON x.ID_CATEGORY = c.ID_CATEGORY;

SELECT '=== L1. the snapshot, and the part that lands on our award categories ===' AS section;

SELECT COUNT(*) AS LIVE_PAIRS, COUNT(DISTINCT ID_CATEGORY) AS LIVE_MEMBERS, COUNT(DISTINCT ID_GROUP) AS LIVE_FAMILIES FROM tmp_071_live;

SELECT COUNT(*) AS PAIRS_ON_OUR_CATEGORIES, COUNT(DISTINCT ID_CATEGORY) AS OUR_CATEGORIES, COUNT(DISTINCT ID_GROUP) AS FAMILIES,
       SUM(BY_P361) AS PAIRS_BY_P361, SUM(BY_P527) AS PAIRS_BY_P527, SUM(BY_P361 = 1 AND BY_P527 = 1) AS PAIRS_BY_BOTH
FROM tmp_071_livecat;

SELECT '=== L2. is the family in our base (ITEM row), and known as a group of awards (its P31)? ===' AS section;

SELECT GROUP_IN_ITEM, GROUP_KNOWN, COUNT(DISTINCT ID_GROUP) AS FAMILIES, COUNT(DISTINCT ID_CATEGORY) AS CATEGORIES
FROM tmp_071_livecat
GROUP BY GROUP_IN_ITEM, GROUP_KNOWN;

SELECT '=== L3. coverage: today (P31), after the load (P31 or P361 or P527, family known), and if every family were cached ===' AS section;

SELECT COUNT(*) AS CATEGORIES, SUM(WINNERS) AS WINNERS,
       SUM(N_P31 > 0) AS CAT_TODAY, SUM(CASE WHEN N_P31 > 0 THEN WINNERS ELSE 0 END) AS WINNERS_TODAY,
       SUM(N_P31 > 0 OR N_P361_KNOWN > 0) AS CAT_WITH_P361, SUM(CASE WHEN N_P31 > 0 OR N_P361_KNOWN > 0 THEN WINNERS ELSE 0 END) AS WINNERS_WITH_P361,
       SUM(N_P31 > 0 OR N_LIVE_KNOWN > 0) AS CAT_WITH_P361_P527, SUM(CASE WHEN N_P31 > 0 OR N_LIVE_KNOWN > 0 THEN WINNERS ELSE 0 END) AS WINNERS_WITH_P361_P527,
       SUM(N_P31 > 0 OR N_LIVE > 0) AS CAT_IF_ALL_CACHED, SUM(CASE WHEN N_P31 > 0 OR N_LIVE > 0 THEN WINNERS ELSE 0 END) AS WINNERS_IF_ALL_CACHED
FROM tmp_071_proj;

SELECT '=== L3b. the same by name (yardstick only) ===' AS section;

SELECT x.NAME_STARTS_WITH, COUNT(*) AS CATEGORIES, SUM(x.WINNERS) AS WINNERS,
       SUM(x.N_P31 > 0) AS CAT_TODAY,
       SUM(x.N_P31 > 0 OR x.N_LIVE_KNOWN > 0) AS CAT_AFTER_LOAD,
       SUM(CASE WHEN x.N_P31 > 0 THEN x.WINNERS ELSE 0 END) AS WINNERS_TODAY,
       SUM(CASE WHEN x.N_P31 > 0 OR x.N_LIVE_KNOWN > 0 THEN x.WINNERS ELSE 0 END) AS WINNERS_AFTER_LOAD,
       SUM(CASE WHEN x.N_P31 = 0 AND x.N_LIVE_KNOWN = 0 THEN x.WINNERS ELSE 0 END) AS WINNERS_STILL_OUT
FROM (SELECT CASE WHEN AWARD_NAME LIKE 'Academy Award%' THEN 'Academy Award'
                  WHEN AWARD_NAME LIKE 'César%' THEN 'Cesar'
                  WHEN AWARD_NAME LIKE 'Golden Globe%' THEN 'Golden Globe'
                  WHEN AWARD_NAME LIKE 'BAFTA%' OR AWARD_NAME LIKE 'British Academy Film%' THEN 'BAFTA'
                  WHEN AWARD_NAME LIKE 'Primetime Emmy%' THEN 'Primetime Emmy'
                  WHEN AWARD_NAME LIKE 'Screen Actors Guild%' THEN 'Screen Actors Guild'
                  WHEN AWARD_NAME LIKE 'Goya%' THEN 'Goya'
                  WHEN AWARD_NAME LIKE 'David di Donatello%' THEN 'David di Donatello'
                  WHEN AWARD_NAME LIKE 'Saturn Award%' THEN 'Saturn Award'
                  WHEN AWARD_NAME LIKE 'Tony Award%' THEN 'Tony Award'
                  WHEN AWARD_NAME LIKE 'Grammy%' THEN 'Grammy'
             END AS NAME_STARTS_WITH, p.*
      FROM tmp_071_proj p) x
WHERE x.NAME_STARTS_WITH IS NOT NULL
GROUP BY x.NAME_STARTS_WITH
ORDER BY WINNERS DESC;

SELECT '=== L3c. the Academy Award... categories still without a family after the load ===' AS section;

SELECT ID_CATEGORY, AWARD_NAME, WINNERS, N_LIVE FROM tmp_071_proj
WHERE AWARD_NAME LIKE 'Academy Award%' AND N_P31 = 0 AND N_LIVE_KNOWN = 0
ORDER BY WINNERS DESC;

SELECT '=== L4. families our base does not know as a group of awards, by what they would carry ===' AS section;

SELECT l.ID_GROUP, COALESCE(MAX(i.LABEL_EN), '') AS LABEL_IN_OUR_BASE, MAX(l.GROUP_IN_ITEM) AS IN_ITEM,
       COUNT(DISTINCT l.ID_CATEGORY) AS CATEGORIES, SUM(l.WINNERS) AS WINNERS
FROM tmp_071_livecat l
LEFT JOIN T_WC_WIKIDATA_ITEM i ON i.ID_WIKIDATA = l.ID_GROUP
WHERE l.GROUP_KNOWN = 0
GROUP BY l.ID_GROUP
ORDER BY WINNERS DESC
LIMIT 40;

SELECT '=== L5. categories by number of distinct families after the load (P31, P361, P527 together) ===' AS section;

SELECT x.FAMILIES, COUNT(*) AS CATEGORIES, SUM(x.WINNERS) AS WINNERS
FROM (SELECT u.ID_CATEGORY, COUNT(DISTINCT u.ID_GROUP) AS FAMILIES, MAX(u.WINNERS) AS WINNERS
      FROM (SELECT t.ID_CATEGORY, t.ID_GROUP, 0 AS WINNERS FROM tmp_071_p31cat t
            UNION ALL
            SELECT l.ID_CATEGORY, l.ID_GROUP, l.WINNERS FROM tmp_071_livecat l WHERE l.GROUP_KNOWN = 1) u
      GROUP BY u.ID_CATEGORY) x
GROUP BY x.FAMILIES
ORDER BY x.FAMILIES;

SELECT '=== L5b. the 30 biggest categories with several families after the load ===' AS section;

SELECT u.ID_CATEGORY, MAX(a.AWARD_NAME) AS AWARD_NAME, COUNT(DISTINCT u.ID_GROUP) AS FAMILIES,
       GROUP_CONCAT(DISTINCT CONCAT(u.ID_GROUP, ' ', COALESCE(i.LABEL_EN, '')) ORDER BY u.ID_GROUP SEPARATOR ' | ') AS FAMILY_LIST,
       MAX(COALESCE(a.MOVIE_COUNT, 0) + COALESCE(a.SERIE_COUNT, 0) + COALESCE(a.PERSON_COUNT, 0)) AS WINNERS
FROM (SELECT t.ID_CATEGORY, t.ID_GROUP FROM tmp_071_p31cat t
      UNION
      SELECT l.ID_CATEGORY, l.ID_GROUP FROM tmp_071_livecat l WHERE l.GROUP_KNOWN = 1) u
JOIN T_WC_T2S_AWARD a ON a.ID_WIKIDATA = u.ID_CATEGORY AND a.AWARD_SOURCE = 'P166'
LEFT JOIN T_WC_WIKIDATA_ITEM i ON i.ID_WIKIDATA = u.ID_GROUP
GROUP BY u.ID_CATEGORY
HAVING COUNT(DISTINCT u.ID_GROUP) > 1
ORDER BY WINNERS DESC
LIMIT 30;

SELECT NOW() AS NOW_;
